#[path = "solution.rs"]
mod solution;

use solution::{total_column, Cell, ColumnError, ColumnTotal, Table};

fn sample_tables() -> Vec<Table> {
    vec![
        Table {
            name: "mixed".to_string(),
            rows: vec![
                vec![Cell::Number(1.0), Cell::Number(2.5)],
                vec![Cell::Text("x".to_string()), Cell::Text("ignored".to_string())],
                vec![Cell::Empty, Cell::Number(-0.5)],
                vec![Cell::Number(9.0)],
            ],
        },
        Table {
            name: "short".to_string(),
            rows: vec![vec![], vec![Cell::Number(4.0)]],
        },
    ]
}

#[test]
fn totals_numbers_and_tracks_column_presence() {
    let tables = sample_tables();
    assert_eq!(
        total_column(&tables, "B"),
        Ok(vec![
            ColumnTotal {
                table_name: "mixed".to_string(),
                present: true,
                sum: 2.0,
            },
            ColumnTotal {
                table_name: "short".to_string(),
                present: false,
                sum: 0.0,
            },
        ])
    );
}

#[test]
fn text_and_empty_cells_still_make_a_column_present() {
    let tables = vec![Table {
        name: "non-numeric".to_string(),
        rows: vec![
            vec![Cell::Text("value".to_string())],
            vec![Cell::Empty],
        ],
    }];
    assert_eq!(
        total_column(&tables, "A"),
        Ok(vec![ColumnTotal {
            table_name: "non-numeric".to_string(),
            present: true,
            sum: 0.0,
        }])
    );
}

#[test]
fn supports_spreadsheet_style_labels() {
    let mut row = vec![Cell::Empty; 28];
    row[25] = Cell::Number(25.0);
    row[26] = Cell::Number(26.0);
    row[27] = Cell::Number(27.0);
    let tables = vec![Table {
        name: "wide".to_string(),
        rows: vec![row],
    }];

    assert_eq!(total_column(&tables, "Z").unwrap()[0].sum, 25.0);
    assert_eq!(total_column(&tables, "AA").unwrap()[0].sum, 26.0);
    assert_eq!(total_column(&tables, "AB").unwrap()[0].sum, 27.0);
}

#[test]
fn rejects_every_malformed_label_class() {
    for label in ["", "a", "Aa", "A1", " A", "A ", "A-B", "É"] {
        assert_eq!(total_column(&[], label), Err(ColumnError::InvalidLabel));
    }
}

#[test]
fn reports_label_conversion_overflow() {
    let oversized = "Z".repeat(100);
    assert_eq!(total_column(&[], &oversized), Err(ColumnError::LabelOverflow));
}

#[test]
fn empty_input_is_empty_and_tables_are_not_mutated() {
    assert_eq!(total_column(&[], "A"), Ok(vec![]));

    let tables = sample_tables();
    let original = tables.clone();
    let first = total_column(&tables, "A");
    let second = total_column(&tables, "A");
    assert_eq!(tables, original);
    assert_eq!(first, second);
}

